{
  "correction_rules": [
    "Adjust forecasts downward when model shows persistent overestimation in early 30-day horizon, especially after recent spikes.",
    "Reduce forecast magnitude by 5-10% if sentiment history is flat (0.00) and true prices show mean reversion toward lower range.",
    "Apply lag correction: if true price dips after model peak, reduce forecast for next 3-5 days by 3-7% to avoid overshoot.",
    "Increase forecast sensitivity to recent low prices if sentiment remains neutral — model should not overreact to minor volatility.",
    "For horizon > 15 days, apply smoothing: if true price deviates > 3% from 14-day moving average, adjust forecast toward that average.",
    "Avoid overconfidence in short-term spikes — if model forecasts a sharp rise after a dip, reduce forecast by 10-15% to account for volatility decay."
  ]
}
